___CSS_LOADER_EXPORT___.push([module.id, `/* Translate independently of each design's existing transform and hover effects. */
@keyframes authority-reveal {
  from {
    opacity: 0;
    translate: 0 10px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes authority-map-reveal {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.au-landing-controls, .au-design-panel > main, .main-portal-workspace, .main-portal-dashboard {
  animation: authority-reveal 560ms cubic-bezier(0.2, 0.7, 0.25, 1) both;
}

.main-portal-dashboard {
  animation-delay: 90ms;
}

.au-explorer .au-project-slot, .au-explorer .au-v-project {
  animation: authority-reveal 620ms cubic-bezier(0.2, 0.7, 0.25, 1) backwards;
  animation-delay: var(--au-reveal-delay, 100ms);
}

.au-project-slot:nth-child(2) {
  --au-reveal-delay:180ms;
}

.au-project-slot:nth-child(3) {
  --au-reveal-delay:260ms;
}

.au-map-stage, .au-v-map {
  animation: authority-map-reveal 800ms ease-out both;
}

.au-territory-popup, .au-landing-language-menu, .custom-map-panel, .portal-profile-popover, .agro-language-menu, .agro-polygon-card {
  animation: authority-reveal 260ms cubic-bezier(0.2, 0.7, 0.25, 1) both;
}

.au-v-project-stats .au-animated-number {
  display: inline;
  font: inherit;
  color: inherit;
}

@media (prefers-reduced-motion: reduce) {
  .au-widget *, .au-widget *::before, .au-widget *::after {
    animation: none !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0s !important;
    scroll-behavior: auto !important;
  }
}`, "",{"version":3,"sources":["webpack://./your-extensions/widgets/authority/src/runtime/motion.css"],"names":[],"mappings":"AAAA,mFAAA;AACA;EACC;IAAO,UAAA;IAAW,iBAAA;EAGjB;EAFD;IAAK,UAAA;IAAW,cAAA;EAMf;AACF;AALA;EAAkC;IAAO,UAAA;EASvC;EAToD;IAAK,UAAA;EAYzD;AACF;AAZA;EAA6F,sEAAA;AAe7F;;AAdA;EAAyB,qBAAA;AAkBzB;;AAjBA;EAA2D,2EAAA;EAAsE,8CAAA;AAsBjI;;AArBA;EAAgC,uBAAA;AAyBhC;;AAxBA;EAAgC,uBAAA;AA4BhC;;AA3BA;EAA0B,mDAAA;AA+B1B;;AA9BA;EAAiI,sEAAA;AAkCjI;;AAjCA;EAA0C,eAAA;EAAgB,aAAA;EAAc,cAAA;AAuCxE;;AAtCA;EACC;IAA0D,0BAAA;IAA0B,sCAAA;IAAqC,+BAAA;IAA+B,gCAAA;EA6CvJ;AACF","sourcesContent":["/* Translate independently of each design's existing transform and hover effects. */\n@keyframes authority-reveal {\n from { opacity:0; translate:0 10px; }\n to { opacity:1; translate:0 0; }\n}\n@keyframes authority-map-reveal { from { opacity:0; } to { opacity:1; } }\n.au-landing-controls,.au-design-panel > main,.main-portal-workspace,.main-portal-dashboard { animation:authority-reveal 560ms cubic-bezier(.2,.7,.25,1) both; }\n.main-portal-dashboard { animation-delay:90ms; }\n.au-explorer .au-project-slot,.au-explorer .au-v-project { animation:authority-reveal 620ms cubic-bezier(.2,.7,.25,1) backwards; animation-delay:var(--au-reveal-delay,100ms); }\n.au-project-slot:nth-child(2) { --au-reveal-delay:180ms; }\n.au-project-slot:nth-child(3) { --au-reveal-delay:260ms; }\n.au-map-stage,.au-v-map { animation:authority-map-reveal 800ms ease-out both; }\n.au-territory-popup,.au-landing-language-menu,.custom-map-panel,.portal-profile-popover,.agro-language-menu,.agro-polygon-card { animation:authority-reveal 260ms cubic-bezier(.2,.7,.25,1) both; }\n.au-v-project-stats .au-animated-number { display:inline; font:inherit; color:inherit; }\n@media(prefers-reduced-motion:reduce) {\n .au-widget *, .au-widget *::before, .au-widget *::after { animation:none!important; transition-duration:.01ms!important; transition-delay:0s!important; scroll-behavior:auto!important; }\n}\n"],"sourceRoot":""}]);
